/**
 * Scenario 3: Verifiable Credential (VC) with Ed25519 local verification
 *
 * Service B verifies the VP signature locally — zero external dependencies.
 * Models fully decentralized trust: no Keycloak, no IdP of any kind.
 *
 * The VP is pre-generated by scripts/generate_vp.py (static file).
 * k6 reads it once and reuses in every request.
 * Service B still verifies the Ed25519 signature on EVERY request.
 *
 * Usage:
 *   python3 scripts/generate_vp.py   # generates vp.json
 *   k6 run -e SERVICE_B_IP=<ip> k6/scenario-3-vc.js
 */

import http from 'k6/http';
import { check } from 'k6';
import { Trend, Rate, Counter } from 'k6/metrics';
import { open } from 'k6/experimental/fs';

const latency    = new Trend('verification_latency', true);
const errorRate  = new Rate('error_rate');
const reqCounter = new Counter('total_requests');

export const options = {
  scenarios: {
    steady_load: {
      executor: 'constant-arrival-rate',
      rate: 100,
      timeUnit: '1s',
      duration: '60s',
      preAllocatedVUs: 50,
      maxVUs: 100,
      startTime: '0s',
    },
    ramp_load: {
      executor: 'ramping-arrival-rate',
      startRate: 10,
      timeUnit: '1s',
      stages: [
        { duration: '20s', target: 50  },
        { duration: '20s', target: 100 },
        { duration: '20s', target: 200 },
        { duration: '20s', target: 50  },
      ],
      preAllocatedVUs: 100,
      maxVUs: 200,
      startTime: '70s',
    },
  },
  thresholds: {
    'verification_latency': ['p(95)<500'],
    'error_rate': ['rate<0.01'],
  },
};

const SERVICE_B_IP = __ENV.SERVICE_B_IP || 'localhost';
const URL          = `http://${SERVICE_B_IP}/api/resource/vc`;

// Load VP once — generated by scripts/generate_vp.py
// Run k6 from the project root: k6 run k6/scenario-3-vc.js
const VP_JSON = open('../vp.json');

export default function () {
  const res = http.post(URL, VP_JSON, {
    headers: { 'Content-Type': 'application/json' },
    timeout: '5s',
  });

  const ok = check(res, {
    'status is 200': (r) => r.status === 200,
    'response allowed': (r) => {
      try { return JSON.parse(r.body).status === 'allowed'; }
      catch { return false; }
    },
  });

  latency.add(res.timings.duration);
  errorRate.add(!ok);
  reqCounter.add(1);
}
